# Plurals: Arabic CLDR forms. App uses %1$d. Provide zero/one/two/few/many/other.
PLURALS = {
 "datetime_months_relative": [
    ("zero", "قبل %1$d شهر"),
    ("one", "قبل شهر واحد"),
    ("two", "قبل شهرين"),
    ("few", "قبل %1$d أشهر"),
    ("many", "قبل %1$d شهراً"),
    ("other", "قبل %1$d شهر"),
 ],
 "datetime_years_relative": [
    ("zero", "قبل %1$d سنة"),
    ("one", "قبل سنة واحدة"),
    ("two", "قبل سنتين"),
    ("few", "قبل %1$d سنوات"),
    ("many", "قبل %1$d سنة"),
    ("other", "قبل %1$d سنة"),
 ],
}

with open(target, 'r', encoding='utf-8') as f:
    content = f.read()

changed = []

# 1) Replace existing <string> entries via regex on raw text (single occurrence each)
for key, val in AR.items():
    if key == "paywall_monthly_note":
        continue  # handled as insert below (NEW)
    pattern = re.compile(r'(<string\s+name="%s"[^>]*>)(.*?)(</string>)' % re.escape(key), re.DOTALL)
    def _repl(m, v=val):
        return m.group(1) + v + m.group(3)
    new_content, n = pattern.subn(_repl, content, count=1)
    if n != 1:
        raise RuntimeError(f"Key {key}: expected exactly 1 replacement, got {n}")
    content = new_content
    changed.append(key)

# 2) NEW key paywall_monthly_note — Pre-Check then rfind insert before </resources>
mn_key = "paywall_monthly_note"
if len(re.findall(r'<string\s+name="%s"' % re.escape(mn_key), content)) > 0:
    # already present (idempotent retry): replace
    pattern = re.compile(r'(<string\s+name="%s"[^>]*>)(.*?)(</string>)' % re.escape(mn_key), re.DOTALL)
    content, n = pattern.subn(lambda m: m.group(1) + AR[mn_key] + m.group(3), content, count=1)
    changed.append(mn_key + " (replaced)")
else:
    new_line = '    <string name="%s">%s</string>' % (mn_key, AR[mn_key])
    idx = content.rfind('</resources>')
    if idx == -1:
        raise RuntimeError("no </resources> found")
    content = content[:idx] + new_line + '\n' + content[idx:]
    changed.append(mn_key + " (inserted)")

# 3) Replace plurals (stale German -> Arabic CLDR)
for pname, items in PLURALS.items():
    body = ""
    for q, t in items:
        body += '\n        <item quantity="%s">%s</item>' % (q, t)
    body += "\n    "
    pattern = re.compile(r'(<plurals\s+name="%s">)(.*?)(</plurals>)' % re.escape(pname), re.DOTALL)
    def _prepl(m, b=body):
        return m.group(1) + b + m.group(3)
    new_content, n = pattern.subn(_prepl, content, count=1)
    if n != 1:
        raise RuntimeError(f"Plural {pname}: expected 1 replacement, got {n}")
    content = new_content
    changed.append("plural:" + pname)

# Atomic write
tmp = target + ".tmp"
with open(tmp, 'w', encoding='utf-8', newline='\n') as f:
    f.write(content)
os.replace(tmp, target)

print("APPLIED:", len(changed), "items")
for c in changed:
    print("  -", c)
